param([Parameter(Mandatory=$true)][string]$ObservedBy)
$ErrorActionPreference='Stop';$secure=Read-Host -Prompt 'Approved recipient (hidden)' -AsSecureString;$pointer=[Runtime.InteropServices.Marshal]::SecureStringToBSTR($secure);try{$env:BEACON_ALERT_RECIPIENT=[Runtime.InteropServices.Marshal]::PtrToStringBSTR($pointer);& node scripts/beacon-gateway-alert-recipient-verification-evidence-admit.mjs "--observed-by=$ObservedBy";if($LASTEXITCODE-ne 0){throw 'Evidence admission failed.'}}finally{[Runtime.InteropServices.Marshal]::ZeroFreeBSTR($pointer);Remove-Item Env:BEACON_ALERT_RECIPIENT -ErrorAction SilentlyContinue}
